using NaughtyAttributes;
using UnityEngine;

namespace Astrea;

public class CustomEventSetup : ScriptableObject
{
	[SerializeField]
	private bool canInitializeAgain;

	[SerializeField]
	private bool muteForDebug;

	[SerializeField]
	private bool enableCustomEventSetupConditionToBeSelected;

	[SerializeField]
	[ShowIf("enableCustomEventSetupConditionToBeSelected")]
	private CustomEventSetupConditionToBeSelected customEventSetupConditionToBeSelected;

	[Header("v1.3 Update")]
	[SerializeField]
	public bool NewEvent;

	public bool CanInitializeAgain => canInitializeAgain;

	public bool MuteForDebug => muteForDebug;

	public virtual void SetupScene()
	{
	}

	public bool CheckConditionToBeSelected()
	{
		if (enableCustomEventSetupConditionToBeSelected)
		{
			return customEventSetupConditionToBeSelected.CheckConditionToBeSelected();
		}
		return true;
	}
}
